var FQ_IMG_DATA = {
  'quality_street': 'data:image/jpeg;base64,',
  'nhs': 'data:image/jpeg;base64,',
  'gq': 'data:image/jpeg;base64,',
  'vogue': 'data:image/jpeg;base64,',
  'nttd': 'data:image/jpeg;base64,',
  'tmwtgg': 'data:image/jpeg;base64,',
  'guardian': 'data:image/jpeg;base64,',
  'sun': 'data:image/jpeg;base64,',
  'guardian25': 'data:image/jpeg;base64,',
  'sun25': 'data:image/jpeg;base64,'
};

// Load images lazily after page renders to avoid blocking HTML parse
window.addEventListener('DOMContentLoaded', function() {
  Object.keys(FQ_IMG_DATA).forEach(function(textId) {
    var el = document.getElementById('fq_img_' + textId);
    if (el) el.src = FQ_IMG_DATA[textId];
  });
});
